import { Redirect } from 'expo-router';
import { View } from 'react-native';
import { useCanModerate } from '../../components/mod';
import { colors } from '../../lib/theme';

// Old People tab. Moderators land on the roster under Chat. Everyone else lands on Chat.
export default function MembersLegacy() {
  const { ready, ok } = useCanModerate();
  if (!ready) return <View style={{ flex: 1, backgroundColor: colors.paper }} />;
  return <Redirect href={ok ? '/chat/members' : '/chat'} />;
}
